// Remote ring bursts are cosmetic: one event per completed step, including an empty blast.
const twinCircleVfxSheet=new Image();twinCircleVfxSheet.assetSrc='assets/twin-circle-vfx-v1.png';BASE_GAME_IMAGES.push(twinCircleVfxSheet);GAME_IMAGES.push(twinCircleVfxSheet);
let twinCircleVfx=[],twinCircleVfxOwner=null,twinCircleVfxResolving=false;
function resetTwinCircleVfx(){twinCircleVfx=[];twinCircleVfxOwner=p;}
function addTwinCircleVfx(x,y){if(twinCircleVfxOwner!==p)resetTwinCircleVfx();if(!started||paused||dead||p.hp<=0||presentationPrefs.reduced||!Number.isFinite(x)||!Number.isFinite(y))return;let limit=effectQuality==='low'?1:2;while(twinCircleVfx.length>=limit)twinCircleVfx.shift();twinCircleVfx.push({x,y,time:0,duration:.6});}
function stepTwinCircleVfx(dt){if(twinCircleVfxOwner!==p||!started||dead||p.hp<=0||presentationPrefs.reduced){resetTwinCircleVfx();return;}if(paused||!Number.isFinite(dt)||dt<=0)return;for(let e of twinCircleVfx)e.time+=dt;twinCircleVfx=twinCircleVfx.filter(e=>e.time<e.duration).slice(-(effectQuality==='low'?1:2));}
function paintTwinCircleVfx(){if(!started||dead||presentationPrefs.reduced||twinCircleVfxOwner!==p||!twinCircleVfxSheet.complete||!twinCircleVfxSheet.naturalWidth||!twinCircleVfxSheet.naturalHeight)return;let low=effectQuality==='low',sw=twinCircleVfxSheet.naturalWidth/4,sh=twinCircleVfxSheet.naturalHeight/2,limit=low?1:2,size=220;for(let e of twinCircleVfx.slice(-limit)){if(!visibleAt(e.x,e.y))continue;let q=project(e.x,e.y);if(q.x<-size||q.x>W+size||q.y<-size||q.y>H+size)continue;let t=clamp(e.time/e.duration,0,1),frame=low?Math.min(3,Math.floor(t*4))*2:Math.min(7,Math.floor(t*8));ctx.save();ctx.globalCompositeOperation='screen';ctx.globalAlpha=t>.75?(1-t)*4:1;ctx.drawImage(twinCircleVfxSheet,(frame%4)*sw,Math.floor(frame/4)*sh,sw,sh,q.x-size/2,q.y-size*.7,size,size);ctx.restore();}}
const twinCircleVfxAreaBase=signatureArea;signatureArea=(s,center,...args)=>{let eligible=!twinCircleVfxResolving&&s?.mode===91&&s.owner===p,previous=twinCircleVfxResolving,result;twinCircleVfxResolving=true;try{result=twinCircleVfxAreaBase(s,center,...args);}finally{twinCircleVfxResolving=previous;}if(eligible)addTwinCircleVfx(center.x,center.y);return result;};
const twinCircleVfxUpdateBase=update;update=dt=>{stepTwinCircleVfx(dt);return twinCircleVfxUpdateBase(dt);};
